drop policy if exists status_media_read on storage.objects;
create policy status_media_read on storage.objects for select to authenticated using(bucket_id='status-media' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.status_updates s where s.media_path=name and s.expires_at>now())));
create or replace function public.status_notify() returns trigger language plpgsql security definer set search_path=public as $$declare recipient uuid; payload jsonb; begin payload:=to_jsonb(new); select owner_id into recipient from public.status_updates where id=new.status_id and expires_at>now(); if recipient is not null and recipient<>new.user_id then insert into public.status_activity(recipient_id,actor_id,status_id,kind,content) values(recipient,new.user_id,new.status_id,case when TG_TABLE_NAME='status_comments' then 'reply' else 'reaction' end,case when TG_TABLE_NAME='status_comments' then payload->>'content' else payload->>'reaction' end); end if; return new; end$$;
revoke all on function public.status_notify() from public;